<?php
$pdo=db();$manager=in_array($user['role'],['Administrator','Head','Bursar'],true);$canSet=in_array($user['role'],['Administrator','Bursar'],true);$canApprove=in_array($user['role'],['Administrator','Head'],true);$canPay=in_array($user['role'],['Administrator','Bursar'],true);$tab=(string)($_GET['tab']??'runs');if(!in_array($tab,['runs','staff'],true))$tab='runs';if(!$manager)$tab='runs';
$runs=[];$selectedRun=null;$lines=[];$items=[];$staffRows=[];$selectedId=filter_var($_GET['run']??null,FILTER_VALIDATE_INT);
if($manager){$runs=$pdo->query('SELECT r.*,u.full_name AS creator_name FROM payroll_runs r LEFT JOIN users u ON u.id=r.created_by ORDER BY r.period_start DESC,r.id DESC LIMIT 60')->fetchAll();if($selectedId){$q=$pdo->prepare('SELECT * FROM payroll_runs WHERE id=:id');$q->execute(['id'=>$selectedId]);$selectedRun=$q->fetch()?:null;}elseif($runs){$selectedRun=$runs[0];$selectedId=(int)$selectedRun['id'];}if($selectedRun){$q=$pdo->prepare("SELECT l.*,COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount ELSE 0 END),0) AS earnings,COALESCE(SUM(CASE WHEN i.item_type='Deduction' THEN i.amount ELSE 0 END),0) AS deductions,l.base_salary+COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount WHEN i.item_type='Deduction' THEN -i.amount ELSE 0 END),0) AS net FROM payroll_lines l LEFT JOIN payroll_line_items i ON i.payroll_line_id=l.id WHERE l.run_id=:run GROUP BY l.id ORDER BY l.staff_name");$q->execute(['run'=>$selectedId]);$lines=$q->fetchAll();if($lines){$ids=array_map('intval',array_column($lines,'id'));$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT * FROM payroll_line_items WHERE payroll_line_id IN ($marks) ORDER BY payroll_line_id,item_type,id");$q->execute($ids);foreach($q->fetchAll() as $item)$items[$item['payroll_line_id']][]=$item;}}if($canSet){$staffRows=$pdo->query("SELECT u.id,u.full_name,u.role,sp.staff_number,sp.job_title,ps.base_salary,ps.currency,ps.effective_from,ps.active AS salary_active FROM users u LEFT JOIN staff_profiles sp ON sp.user_id=u.id LEFT JOIN staff_pay_settings ps ON ps.staff_id=u.id WHERE u.active=1 AND u.role IN ('Administrator','Head','Teacher','Bursar','Clerk') ORDER BY FIELD(u.role,'Head','Teacher','Bursar','Clerk','Administrator'),u.full_name")->fetchAll();}}
else{$q=$pdo->prepare("SELECT DISTINCT r.* FROM payroll_runs r JOIN payroll_lines l ON l.run_id=r.id WHERE l.staff_id=:staff AND r.status='Paid' ORDER BY r.period_start DESC LIMIT 60");$q->execute(['staff'=>$user['id']]);$runs=$q->fetchAll();if($selectedId){$q=$pdo->prepare("SELECT r.* FROM payroll_runs r JOIN payroll_lines l ON l.run_id=r.id WHERE r.id=:run AND l.staff_id=:staff AND r.status='Paid' LIMIT 1");$q->execute(['run'=>$selectedId,'staff'=>$user['id']]);$selectedRun=$q->fetch()?:null;}elseif($runs){$selectedRun=$runs[0];$selectedId=(int)$selectedRun['id'];}if($selectedRun){$q=$pdo->prepare("SELECT l.*,COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount ELSE 0 END),0) AS earnings,COALESCE(SUM(CASE WHEN i.item_type='Deduction' THEN i.amount ELSE 0 END),0) AS deductions,l.base_salary+COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount WHEN i.item_type='Deduction' THEN -i.amount ELSE 0 END),0) AS net FROM payroll_lines l LEFT JOIN payroll_line_items i ON i.payroll_line_id=l.id WHERE l.run_id=:run AND l.staff_id=:staff GROUP BY l.id");$q->execute(['run'=>$selectedId,'staff'=>$user['id']]);$lines=$q->fetchAll();if($lines){$q=$pdo->prepare('SELECT * FROM payroll_line_items WHERE payroll_line_id=:line ORDER BY item_type,id');$q->execute(['line'=>$lines[0]['id']]);$items[$lines[0]['id']]=$q->fetchAll();}}}
?>
