<?php elseif($manager): ?>
<section class="panel settings-panel no-print"><div class="panel-heading"><div><h2>Start a payroll run</h2><p>Creates a draft snapshot for active staff with an effective salary in the selected currency.</p></div></div><form method="post" action="actions/payroll_run_create.php" class="compact-form"><?= csrf_field() ?><label>Period start<input type="date" name="period_start" value="<?= h(date('Y-m-01')) ?>" required></label><label>Period end<input type="date" name="period_end" value="<?= h(date('Y-m-t')) ?>" required></label><label>Currency<select name="currency"><option>USD</option><option>ZiG</option></select></label><button class="primary-button">Create draft run</button></form></section>
<section class="panel learners-panel no-print"><div class="panel-heading"><div><h2>Payroll run history</h2><p>Latest 60 school payroll runs</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Period</th><th>Currency</th><th>Staff</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($runs as $run): ?><tr><td><?= h(date('d M Y',strtotime($run['period_start']))) ?> – <?= h(date('d M Y',strtotime($run['period_end']))) ?></td><td><?= h($run['currency']) ?></td><td><?php $q=$pdo->prepare('SELECT COUNT(*) FROM payroll_lines WHERE run_id=:run');$q->execute(['run'=>$run['id']]);echo (int)$q->fetchColumn(); ?></td><td><span class="status-pill"><?= h($run['status']) ?></span></td><td><?= h(date('d M Y',strtotime($run['created_at']))) ?></td><td><a class="text-button" href="?page=payroll&run=<?= (int)$run['id'] ?>">Open run →</a></td></tr><?php endforeach; if(!$runs): ?><tr><td colspan="6" class="empty-cell">No payroll runs have been created.</td></tr><?php endif; ?></tbody></table></div></section>
<?php endif; ?>
<?php if($selectedRun&&($manager||$selectedRun['status']==='Paid')): ?>
<?php if($manager): ?><section class="panel settings-panel no-print"><div class="panel-heading"><div><h2>Run: <?= h(date('d M Y',strtotime($selectedRun['period_start']))) ?> – <?= h(date('d M Y',strtotime($selectedRun['period_end']))) ?> · <?= h($selectedRun['currency']) ?></h2><p>Status: <b><?= h($selectedRun['status']) ?></b> · Each line snapshots the salary and item changes for this run.</p></div></div><?php if($selectedRun['status']==='Draft'): ?><p class="privacy-note">Add allowances, overtime, statutory deductions and other authorized items to each staff row. Verify applicable Zimbabwe payroll rules and rates before approving; the system does not calculate statutory deductions automatically.</p><?php endif; ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Staff member</th><th>Base</th><th>Items</th><th>Earnings</th><th>Deductions</th><th>Net pay</th></tr></thead><tbody><?php foreach($lines as $line): ?><tr><td><b><?= h($line['staff_name']) ?></b><?php if($line['staff_number']): ?><small class="muted-cell"><?= h($line['staff_number']) ?></small><?php endif; ?><?php if($line['job_title']): ?><small class="muted-cell"><?= h($line['job_title']) ?></small><?php endif; ?></td><td><?= h($line['currency']) ?> <?= number_format((float)$line['base_salary'],2) ?></td><td><?php foreach($items[$line['id']]??[] as $item): ?><div><?= h($item['item_type']) ?> · <?= h($item['description']) ?>: <?= number_format((float)$item['amount'],2) ?><?php if($selectedRun['status']==='Draft'&&$canSet): ?><form method="post" action="actions/payroll_item_save.php" style="display:inline"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$selectedRun['id'] ?>"><input type="hidden" name="line_id" value="<?= (int)$line['id'] ?>"><input type="hidden" name="delete_item_id" value="<?= (int)$item['id'] ?>"><button class="text-button">Remove</button></form><?php endif; ?></div><?php endforeach; ?><?php if($selectedRun['status']==='Draft'&&$canSet): ?><form method="post" action="actions/payroll_item_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$selectedRun['id'] ?>"><input type="hidden" name="line_id" value="<?= (int)$line['id'] ?>"><select name="item_type"><option>Earning</option><option>Deduction</option></select><input name="description" maxlength="120" required placeholder="e.g. NSSA"><input type="number" name="amount" min="0.01" step="0.01" required placeholder="Amount"><button class="outline-button compact-button">Add</button></form><?php endif; ?></td><td><?= h($line['currency']) ?> <?= number_format((float)$line['earnings'],2) ?></td><td><?= h($line['currency']) ?> <?= number_format((float)$line['deductions'],2) ?></td><td><b><?= h($line['currency']) ?> <?= number_format((float)$line['net'],2) ?></b></td></tr><?php endforeach; if(!$lines): ?><tr><td colspan="6" class="empty-cell">This run contains no staff. Create a run after configuring salaries.</td></tr><?php endif; ?></tbody></table></div><?php if($selectedRun['status']==='Draft'): ?><div class="form-actions"><?php if($canApprove&&(int)$selectedRun['created_by']!==(int)$user['id']): ?><form method="post" action="actions/payroll_transition.php" onsubmit="return confirm('Approve this payroll snapshot?')"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$selectedRun['id'] ?>"><button class="primary-button" name="action" value="Approve">Approve payroll</button></form><?php elseif($canApprove): ?><span class="muted-cell">Run creator cannot approve this payroll.</span><?php endif; ?><?php if($user['role']==='Administrator'): ?><form method="post" action="actions/payroll_transition.php" onsubmit="return confirm('Void this draft payroll?')"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$selectedRun['id'] ?>"><button class="outline-button" name="action" value="Void">Void draft</button></form><?php endif; ?></div><?php elseif($selectedRun['status']==='Approved'&&$canPay&&(int)$selectedRun['approved_by']!==(int)$user['id']): ?><form method="post" action="actions/payroll_transition.php" class="compact-form no-print"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$selectedRun['id'] ?>"><input type="hidden" name="action" value="MarkPaid"><label>Payment reference<input name="payment_reference" maxlength="120" required placeholder="Bank batch / payment reference"></label><button class="primary-button">Record paid</button></form><?php elseif($selectedRun['status']==='Approved'&&$canPay): ?><p class="privacy-note no-print">A different staff member must record payment after approval.</p><?php endif; ?></section><?php endif; ?>
<?php if(!$manager&&$runs): ?><section class="panel learners-panel no-print"><div class="panel-heading"><div><h2>Your payslips</h2><p>Only paid payroll periods are listed.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Period</th><th>Currency</th><th>Paid date</th><th></th></tr></thead><tbody><?php foreach($runs as $run): ?><tr><td><?= h(date('d M Y',strtotime($run['period_start']))) ?> – <?= h(date('d M Y',strtotime($run['period_end']))) ?></td><td><?= h($run['currency']) ?></td><td><?= h(date('d M Y',strtotime($run['paid_at']))) ?></td><td><a class="text-button" href="?page=payroll&run=<?= (int)$run['id'] ?>">Open payslip →</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php elseif(!$manager&&!$runs): ?><section class="panel settings-panel"><h2>No payslips yet</h2><p>Paid payslips will appear here when the school processes payroll.</p></section><?php endif; ?>
<?php if($selectedRun&&$selectedRun['status']==='Paid'&&$lines): ?><section class="panel payroll-slip"><div class="panel-heading"><div><div class="eyebrow">CONFIDENTIAL PAYSLIP</div><h2><?= h($schoolDisplayName??'School') ?></h2><p><?= h(date('d M Y',strtotime($selectedRun['period_start']))) ?> – <?= h(date('d M Y',strtotime($selectedRun['period_end']))) ?></p></div></div><?php foreach($lines as $line): ?><div class="receipt-grid"><div><small>Staff member</small><b><?= h($line['staff_name']) ?></b></div><div><small>Staff number</small><b><?= h($line['staff_number']?:'—') ?></b></div><div><small>Job title</small><b><?= h($line['job_title']?:'—') ?></b></div><div><small>Currency</small><b><?= h($line['currency']) ?></b></div></div><table class="receipt-lines"><thead><tr><th>Pay item</th><th>Amount</th></tr></thead><tbody><tr><td>Base salary</td><td><?= h($line['currency']) ?> <?= number_format((float)$line['base_salary'],2) ?></td></tr><?php foreach($items[$line['id']]??[] as $item): ?><tr><td><?= h($item['item_type']) ?> · <?= h($item['description']) ?></td><td><?= $item['item_type']==='Deduction'?'−':'' ?><?= h($line['currency']) ?> <?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th>Net pay</th><th><?= h($line['currency']) ?> <?= number_format((float)$line['net'],2) ?></th></tr></tfoot></table><p class="receipt-note">Paid <?= h(date('d M Y H:i',strtotime($selectedRun['paid_at']))) ?> · Reference <?= h($selectedRun['payment_reference']?:'—') ?></p><?php endforeach; ?></section><?php endif; ?>
<?php endif; ?>
